 function source(relative){
  try{return sourcePath(r.workspace,relative)}catch(e){if(e.message==='unsafe bundle path')gap('unsafe bundle path: '+relative);throw e}
 }
 // Destination parents belong to this archive too. Never hash, trust or copy a
